const mois = [
  'janvier', 'février', 'mars', 'avril', 'mai', 'juin',
  'juillet', 'août', 'septembre', 'octobre', 'novembre', 'décembre'
];

const now = new Date();
const moisCourant = mois[now.getMonth()];
const annee = now.getFullYear();

const subject = `Demande de facture d'électricité – ${moisCourant} ${annee}`;

const text = `Bonjour SRM Casablanca-Settat,

Nous sommes la société Briqueterie JBEL ANNOUR.

Merci de nous transmettre la facture d'électricité du mois de ${moisCourant} ${annee}.

Veuillez nous l'envoyer en réponse à cet email.

Cordialement,
Briqueterie JBEL ANNOUR`;

const html = `<p>Bonjour SRM Casablanca-Settat,</p>
<p>Nous sommes la société <b>Briqueterie JBEL ANNOUR</b>.</p>
<p>Merci de nous transmettre la facture d'électricité du mois de <b>${moisCourant} ${annee}</b>.</p>
<p>Veuillez nous l'envoyer <b>en réponse à cet email</b>.</p>
<p>Cordialement,<br>Briqueterie JBEL ANNOUR</p>`;

return [{ json: { subject, text, html } }];
